<style>
  :root{
    --bg:#0b0d12; --panel:#12151d; --line:#232838; --ink:#e8e6df; --dim:#8b90a0;
    --accent:#e8b44a;
  }
  *{box-sizing:border-box; margin:0}
  html,body{height:100%}
  body{background:var(--bg); color:var(--ink); font-family:'IBM Plex Sans',sans-serif; overflow:hidden}
  header{position:fixed; top:0; left:0; right:0; z-index:10; display:flex; align-items:center; gap:16px;
    padding:14px 20px; background:linear-gradient(#0b0d12f0,#0b0d1200); pointer-events:none}
  header *{pointer-events:auto}
  header h1{font-family:'Cormorant Garamond',serif; font-weight:700; font-size:22px; letter-spacing:.5px}
  header h1 em{color:var(--accent); font-style:normal}
  header .sub{font-size:12px; color:var(--dim)}
  #searchwrap{position:relative; margin-left:auto; width:min(340px,45vw)}
  #search{width:100%; padding:9px 14px; border-radius:999px; border:1px solid var(--line);
    background:var(--panel); color:var(--ink); font:inherit; font-size:14px; outline:none}
  #search:focus{border-color:var(--accent)}
  #suggest{position:absolute; top:110%; left:0; right:0; max-height:300px; overflow:auto; display:none;
    background:var(--panel); border:1px solid var(--line); border-radius:12px; box-shadow:0 12px 32px #0009}
  #suggest div{padding:8px 14px; cursor:pointer; font-size:14px; display:flex; justify-content:space-between; gap:8px}
  #suggest div span.deg{color:var(--dim); font-size:12px}
  #suggest div:hover,#suggest div.active{background:#1c2230}
  #canvas{position:fixed; inset:0}
  #panel{position:fixed; top:64px; right:16px; bottom:16px; width:min(360px,86vw); z-index:9;
    background:#12151df2; border:1px solid var(--line); border-radius:16px; padding:22px;
    overflow:auto; backdrop-filter:blur(6px); display:none}
  #panel h2{font-family:'Cormorant Garamond',serif; font-size:40px; line-height:1.05; font-weight:700; word-break:break-word}
  #panel .tema{display:inline-block; margin:8px 0 4px; font-size:12px; letter-spacing:1.5px; text-transform:uppercase;
    color:var(--accent); border:1px solid #e8b44a55; border-radius:999px; padding:3px 10px}
  #panel .close{position:absolute; top:10px; right:12px; background:none; border:none; color:var(--dim);
    font-size:20px; cursor:pointer}
  #panel .close:hover{color:var(--ink)}
  .relgroup{margin-top:18px}
  .relgroup h3{font-size:11px; text-transform:uppercase; letter-spacing:1.5px; color:var(--dim); margin-bottom:8px}
  .chips{display:flex; flex-wrap:wrap; gap:8px}
  .chip{border:1px solid var(--line); background:#1a1f2c; color:var(--ink); border-radius:999px;
    padding:5px 12px; font-size:13px; cursor:pointer; transition:.15s}
  .chip:hover{border-color:var(--accent); color:var(--accent)}
  #panel .note{margin-top:20px; font-size:12px; color:var(--dim); line-height:1.6}
  #hint{position:fixed; left:20px; bottom:16px; z-index:9; color:var(--dim); font-size:12px; line-height:1.7}
  #stats{position:fixed; left:20px; top:64px; z-index:9; color:var(--dim); font-size:12px}
  #loading{position:fixed; inset:0; display:flex; align-items:center; justify-content:center; color:var(--dim)}
  @media (max-width:640px){ #panel{top:auto; height:55vh} #stats{display:none} }
</style>
</head>
